$msg='';$err='';$uploads=dirname(__DIR__,2).'/uploads/';$sectores=sectoresEditables($pdo);if(!$sectores){http_response_code(403);exit('No tenés sectores habilitados para editar.');}$sectorIds=array_map(fn($s)=>(int)$s['id'],$sectores);$sid=(int)($_REQUEST['sector_id']??$sectorIds[0]);if(!in_array($sid,$sectorIds,true)){if($_SERVER['REQUEST_METHOD']==='POST'){http_response_code(403);exit('No tenés permiso para gestionar carpetas en ese sector.');}$sid=$sectorIds[0];}
function folderDescendants(PDO $pdo,int $sid,int $id): array {$out=[];$queue=[$id];$seen=[];while($queue){$current=array_shift($queue);if(isset($seen[$current]))throw new RuntimeException('Se detectó un ciclo en la estructura de carpetas.');$seen[$current]=true;$st=$pdo->prepare('SELECT id FROM carpetas WHERE sector_id=? AND carpeta_padre_id=?');$st->execute([$sid,$current]);foreach($st->fetchAll(PDO::FETCH_COLUMN) as $child){$child=(int)$child;$out[]=$child;$queue[]=$child;}}return$out;}
function folderFlat(PDO $pdo,int $sid): array {$st=$pdo->prepare('SELECT id,nombre,carpeta_padre_id,orden,activa FROM carpetas WHERE sector_id=? AND activa=1 AND eliminado_lote IS NULL ORDER BY orden,nombre');$st->execute([$sid]);$all=$st->fetchAll();$by=[];foreach($all as $f)$by[$f['carpeta_padre_id']??0][]=$f;$out=[];$walk=function($p,$prefix,$level)use(&$walk,&$out,&$by){foreach($by[$p]??[] as $f){$f['label']=$prefix.$f['nombre'];$f['level']=$level;$out[]=$f;$walk($f['id'],$prefix.'— ',$level+1);}};$walk(0,'',0);return$out;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!puedeEditarSector($pdo,$sid)){http_response_code(403);exit('No tenés permiso de edición para este sector.');}
 $action=$_POST['accion']??'';
 try{
  $pdo->beginTransaction();
  if($action==='crear'){$name=trim($_POST['nombre']??'');$parent=!empty($_POST['carpeta_padre_id'])?(int)$_POST['carpeta_padre_id']:null;if($name==='')throw new RuntimeException('Ingresá un nombre.');validarCarpetaSector($pdo,$sid,$parent);$pdo->prepare('INSERT INTO carpetas(sector_id,nombre,carpeta_padre_id,orden,activa) VALUES(?,?,?,?,1)')->execute([$sid,mb_substr($name,0,160),$parent,(int)($_POST['orden']??0)]);registrarActividad($pdo,'crear_carpeta',$name);$msg='Carpeta creada.';}
  if($action==='editar'){$id=(int)($_POST['id']??0);$name=trim($_POST['nombre']??'');$parent=!empty($_POST['carpeta_padre_id'])?(int)$_POST['carpeta_padre_id']:null;if($id<=0||$name==='')throw new RuntimeException('Datos incompletos.');if($parent===$id)throw new RuntimeException('Una carpeta no puede depender de sí misma.');validarCarpetaSector($pdo,$sid,$id);validarCarpetaSector($pdo,$sid,$parent);$desc=folderDescendants($pdo,$sid,$id);if($parent&&in_array($parent,$desc,true))throw new RuntimeException('No se puede mover una carpeta dentro de una subcarpeta propia.');$pdo->prepare('UPDATE carpetas SET nombre=?,carpeta_padre_id=?,orden=? WHERE id=? AND sector_id=?')->execute([mb_substr($name,0,160),$parent,(int)($_POST['orden']??0),$id,$sid]);registrarActividad($pdo,'editar_carpeta',$name);$msg='Carpeta actualizada.';}
  if($action==='eliminar'){$id=(int)($_POST['id']??0);validarCarpetaSector($pdo,$sid,$id);$ids=array_merge([$id],folderDescendants($pdo,$sid,$id));$ph=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT COUNT(*) FROM carpetas WHERE carpeta_padre_id IN ($ph) AND sector_id<>?");$st->execute([...$ids,$sid]);if((int)$st->fetchColumn())throw new RuntimeException('La estructura contiene carpetas de otro sector. Corregí esa relación antes de eliminar.');$st=$pdo->prepare("SELECT COUNT(*) FROM documentos WHERE sector_id<>? AND carpeta_id IN ($ph)");$st->execute([$sid,...$ids]);if((int)$st->fetchColumn())throw new RuntimeException('La carpeta contiene documentos de otro sector. Corregí esa relación antes de eliminar.');$nombre=$pdo->query('SELECT nombre FROM carpetas WHERE id='.(int)$id)->fetchColumn();$lote=enviarPapelera($pdo,'carpeta',$id,$sid,(string)$nombre);$pdo->prepare("UPDATE documentos SET activo=0,eliminado_lote=? WHERE sector_id=? AND activo=1 AND eliminado_lote IS NULL AND carpeta_id IN ($ph)")->execute([$lote,$sid,...$ids]);$pdo->prepare("UPDATE carpetas SET activa=0,eliminado_lote=? WHERE sector_id=? AND activa=1 AND eliminado_lote IS NULL AND id IN ($ph)")->execute([$lote,$sid,...$ids]);registrarActividad($pdo,'eliminar_carpeta',"Carpeta $id y ".(count($ids)-1).' subcarpetas');$msg='Carpeta y contenido movidos a la papelera. Se pueden recuperar.';}
  $pdo->commit();
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=mensaje_error($e);}
}
$folders=folderFlat($pdo,$sid);$selectedSector=array_values(array_filter($sectores,fn($s)=>(int)$s['id']===$sid))[0]??$sectores[0];
