<div class="admin-layout"><section class="form-panel"><p class="eyebrow">NUEVA CARPETA</p><h2>Crear carpeta</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="accion" value="crear"><input type="hidden" name="sector_id" value="<?=$sid?>"><label>Nombre<input name="nombre" required placeholder="Ej: Procedimientos operativos"></label><label>Dentro de<select name="carpeta_padre_id"><option value="">Raíz de <?=h($selectedSector['nombre'])?></option><?php foreach($folders as $f):?><option value="<?=$f['id']?>"><?=h($f['label'])?></option><?php endforeach;?></select></label><label>Orden<input type="number" name="orden" value="0"></label><button class="btn primary">Crear carpeta</button></form></section><section class="table-panel"><div class="section-head"><div><p class="eyebrow">ESTRUCTURA</p><h2><?=h($selectedSector['nombre'])?></h2></div><span class="count-pill"><?=count($folders)?> carpeta(s)</span></div><?php if(!$folders):?><div class="empty">Todavía no hay carpetas.</div><?php endif;?><div class="folder-admin-list"><?php foreach($folders as $f):?><details class="folder-admin-item"><summary><span><?=str_repeat('&nbsp;&nbsp;',min(4,$f['level']))?>📁 <?=h($f['nombre'])?></span><small>Editar</small></summary><form method="post" class="folder-edit"><?=csrf_field()?><input type="hidden" name="accion" value="editar"><input type="hidden" name="sector_id" value="<?=$sid?>"><input type="hidden" name="id" value="<?=$f['id']?>"><div class="form-row"><label>Nombre<input name="nombre" value="<?=h($f['nombre'])?>" required></label><label>Mover dentro de<select name="carpeta_padre_id"><option value="">Raíz</option><?php foreach($folders as $p):if((int)$p['id']===(int)$f['id'])continue;?><option value="<?=$p['id']?>" <?=(int)($f['carpeta_padre_id']??0)===(int)$p['id']?'selected':''?>><?=h($p['label'])?></option><?php endforeach;?></select></label><label>Orden<input type="number" name="orden" value="<?=$f['orden']?>"></label></div><div class="table-actions"><button class="btn secondary">Guardar cambios</button></form><form method="post" onsubmit="return confirm('¿Mover esta carpeta y su contenido a la papelera?')"><?=csrf_field()?><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="sector_id" value="<?=$sid?>"><input type="hidden" name="id" value="<?=$f['id']?>"><button class="btn danger" type="submit">A papelera</button></form></div></details><?php endforeach;?></div></section></div></main></div></body></html>
